	if r == nil {
		return fmt.Errorf("%w: 创建批次请求 %q（批次 %q）原选配方 %q 版本 %q 未登记，保存的创建结果不能单独作为创建成功的依据",
			ErrCorruptData, reqNo, batchNo, payload.RecipeNo, payload.Version)
	}
